local UIMainChapterSideLinePopupNode = Class("UIMainChapterSideLinePopupNode")
function UIMainChapterSideLinePopupNode:__init()
    self._curQuestVo = nil
    self._cb = nil
end

function UIMainChapterSideLinePopupNode:__delete()
    self._curQuestVo = nil
    self._cb = nil
end

function UIMainChapterSideLinePopupNode:Awake()
end

function UIMainChapterSideLinePopupNode:Start()
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnQuest))
end

function UIMainChapterSideLinePopupNode:Refresh(questId, cb)
    self._curQuestVo = QuestConfMgr:GetInstance():GetQuestSideVo(questId)
    if not self._curQuestVo then
        return
    end

    self._cb = cb
    self:FillSelf()
end

function UIMainChapterSideLinePopupNode:FillSelf()
    local isUnlock, err = QuestConfMgr:GetInstance():IsUnlockSideQuest(self._curQuestVo.id)
    CfUtils.FillImage(self.ImgTask, self._curQuestVo.image)
    CfUtils.FillText(self.TxtName, self._curQuestVo.name)

    CfUtils.SetActive(self.LockGroup, not isUnlock)
    CfUtils.SetActive(self.FontStyleButton, isUnlock)
    local hasDrawn = 0
    if isUnlock then
        local isPass = QuestConfMgr:GetInstance():IsPassSideQuest(self._curQuestVo.id) 
        if not isPass then
            self.FontStyleButton:ResetFontStyle("B23", localize("阅读"))
        else
            hasDrawn = 1
            self.FontStyleButton:ResetFontStyle("B24", localize("回顾"))
        end
    else
        CfUtils.FillText(self.TxtDesc, err)
    end

    local t1 = checkTable(CfUtils.Split(self._curQuestVo.rewardId))
    local t2 = checkTable(CfUtils.Split(self._curQuestVo.rewardNum))

    for i = 1, table.count(t1) do
        local go = self.GoodList.transform:Find("go"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.Good, self.GoodList)
            go.name = "go"..i
        end
        CfUtils.SetActive(go, true)
        local goodNode = go.transform:Find("GoodNode")
        local getImageTrans = goodNode.transform:Find("getimg")
        KTool.SetActive(getImageTrans, hasDrawn == 1)
        CfUtils.RefeshGoodGo2(goodNode, t1[i], t2[i], nil, nil, function()
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(t1[i])
            GameUtils.ShowCommonTipsBoard(go, vo.name, vo.desc, vo.quality, vo.id)
        end)
    end

    for i = table.count(t1) + 1, self.GoodList.transform.childCount do
        local go = self.GoodList.transform:Find("go"..i)
        if go then
            CfUtils.SetActive(go, false)
        end
    end
end

function UIMainChapterSideLinePopupNode:OnBtnQuest()
    local isUnlock, err = QuestConfMgr:GetInstance():IsUnlockSideQuest(self._curQuestVo.id)
    if not isUnlock then
        GameUtils.Toast(err)
        return
    end
    if self._cb then
        self._cb()
    end
end

function UIMainChapterSideLinePopupNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIMainChapterSideLinePopupNode